  // Altin - tek tacli olan bu.
  {
    ust: '#FFE9A8', alt: '#D9A21B', kenar: '#B07C0A',
    yazi: '#6B4A00', dal: '#DFAE2E', tac: true,
  },
  // Gumus
  {
    ust: '#F6F8FA', alt: '#A9B3BB', kenar: '#8A959D',
    yazi: '#465158', dal: '#B4BCC3', tac: false,
